import java.io.*;
import java.net.*;
import java.nio.file.*;
/** Deterministic knockout in the first shot; drain the entire committed action and result delay. */
public final class HF42FinishCheck {
 static int checks;
 static void ok(boolean value,String msg){if(!value)throw new AssertionError(msg);checks++;}
 static final Battle.Ground flat=new Battle.Ground(){public boolean solid(int x,int y){return y>=180;}public int surface(int x,int y){return 180;}public void crater(int x,int y,int r){}};
 static Battle base(int stage,int diff){Battle b=new Battle(flat);b.start(true);if(stage>0){b.configureOnlineTeam();b.units[2].hp=b.units[4].hp=0;b.explicitHumans=true;b.units[0].human=true;if(stage>=3)TribalRules.setup(b,stage-2,diff,false);else{b.dungeonStage=stage;b.dungeonDifficulty=diff;if(stage==2)AntCaveRules.spawn(b,1,3,diff);for(int i=2;i<b.unitCount;i++)b.units[i].hp=0;}b.tribalFx=0;b.tribalState=TribalRules.IDLE;b.botPhase=0;if(stage==6){TribalRules.spawn(b,1,TribalRules.RAGE,320);b.tribalPhase=2;}}
  b.active=0;b.units[0].human=true;b.units[0].hp=b.units[0].maxHp=30000;b.units[0].x=80;b.units[0].y=180;b.units[0].weapon=3;b.units[0].face=1;b.units[0].angle=40;b.units[0].power=70;b.wind=0;b.deferNext=true;b.tribalClock=0;
  for(int i=1;i<b.unitCount;i++)if(b.units[i].team==1||stage==0&&i==1){b.units[i].hp=0;b.units[i].dead=true;}
  b.units[1].hp=1;b.units[1].dead=false;b.units[1].x=320;b.units[1].y=180;if(stage==3){b.units[1].npc=TribalRules.SPEAR;b.tribalGoal=1;}
  return b;
 }
 static void aimAt(Battle b,int target){for(int i=0;i<b.ballCount;i++){Battle.Ball p=b.balls[i];p.homing=p.guided=false;p.x=b.units[target].x*256;p.y=181*256;p.vx=p.vy=0;}}
 static void delay(Battle b,int result){ok(b.ending()&&!b.over&&!b.input(),"latched result blocks input");int turn=b.turn;ok(b.settle==Battle.RESULT_DELAY_TICKS,"full hold starts after action");for(int i=1;i<Battle.RESULT_DELAY_TICKS;i++){b.tick();ok(!b.over&&b.turn==turn&&!b.input(),"no summary or new turn during hold");}b.tick();ok(b.over&&b.winner==result&&b.winSerial==1,"summary only after full delay");b.tick();ok(b.winSerial==1,"no duplicate win");}
 static void volley(int stage,int diff,int shots,boolean triple){Battle b=base(stage,diff);b.extra=shots-1;b.triple=triple;b.fire();int start=b.turn;int firstKill=-1;
  for(int i=0;i<1800&&!b.ending();i++){if(b.ballCount>0)aimAt(b,1);b.tick();if(b.units[1].hp==0&&firstKill<0)firstKill=b.shotSerial;if(b.shotSerial<shots){ok(!b.over&&!b.ending()&&b.turn==start,"first lethal hit cannot end committed volley");ok(b.tribalFx==0,"no cutscene interrupts remaining rounds");}}
  ok(firstKill==1,"first wave was lethal");ok(b.shotSerial==shots&&b.ballCount==0&&b.bursts==0,"all waves emitted and landed");ok(b.kills[0]==1,"dead targets not counted twice");delay(b,0);
 }
 static void golden(){Battle b=base(6,0);TribalRules.spawn(b,1,TribalRules.SULAN,320);b.tribalPhase=1;b.units[1].hp=1;b.extra=2;b.fire();for(int i=0;i<1000&&b.tribalFx==0;i++){if(b.ballCount>0)aimAt(b,1);b.tick();}ok(b.shotSerial==3&&b.ballCount==0&&b.bursts==0&&b.tribalState==TribalRules.TRANSFORM,"golden transformation follows entire volley");for(int i=0;i<SulanRules.TRANSFORM;i++)b.tick();ok(!b.over&&b.tribalPhase==2,"red form still appears");}
 static void redWipe(){Battle b=base(6,2);b.units[1].hp=b.units[1].maxHp=30000;b.units[1].power=0;b.units[0].hp=1;b.active=1;b.tribalClock=0;b.tribalWave=0;for(int i=0;i<1600&&!b.ending();i++){for(int j=0;j<b.ballCount;j++){Battle.Ball p=b.balls[j];p.x=b.units[0].x*256;p.y=181*256;p.vx=p.vy=0;}b.tick();}ok(b.units[0].hp==0&&b.shotSerial==12&&b.ballCount==0,"red boss finishes four casts even after party wipe");delay(b,1);}
 static void damage(){Battle b=base(0,0);var a=b.units[0];var v=b.units[1];v.hp=v.maxHp=30000;a.statsEnabled=v.statsEnabled=true;a.luck=1000;v.defense=600;int crit=0,penetration=0;for(int i=0;i<100;i++){b.shotSerial=i;int raw=1600,x=v.x*256,y=Battle.targetY(v)*256;boolean c=CombatBalance.roll(b,0,1,x,y,0)<CombatBalance.critChance(a.luck);if(c)crit++;else penetration++;var p=new Battle.Ball();p.owner=0;p.damage=raw;p.radius=1;p.x=x;p.y=y;v.hp=30000;b.impact(p);var popup=b.damagePopups[b.damagePopupCount-1];ok(popup.powered,"crit or effective penetration uses POW flag");ok(popup.value==(c?1680:1120),"unchanged balance formula");}ok(crit>0&&penetration>0,"both visual paths tested");a.luck=0;v.hp=30000;var p=new Battle.Ball();p.owner=0;p.damage=1600;p.radius=1;p.x=v.x*256;p.y=Battle.targetY(v)*256;b.impact(p);ok(!b.damagePopups[b.damagePopupCount-1].powered,"normal remains normal");p.powered=true;b.impact(p);ok(b.damagePopups[b.damagePopupCount-1].powered,"POW retained");v.defense=0;a.luck=1000;boolean onlyCrit=CombatBalance.roll(b,0,1,p.x,p.y,0)<CombatBalance.critChance(a.luck);ok(CombatBalance.special(b,0,1,p.damage,p.x,p.y,0)==onlyCrit,"no fake penetration on zero armor");}
 static void room()throws Exception{try(var s=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),new CloudStore.Memory())){s.clock.shutdownNow();var r=ShotBatchHF10Check.room(s,true,0,2);var b=r.battle;b.units[1].hp=1;for(int i=0;i<1500&&!b.ending();i++){if(b.ballCount>0)aimAt(b,1);r.tick();}ok(b.ending()&&!r.settlementQueued&&r.phase==1,"room keeps battle alive during result delay");int turn=b.turn;for(int i=1;i<Battle.RESULT_DELAY_TICKS;i++){r.tickAhead();ok(!b.over&&r.phase==1&&!r.settlementQueued&&b.turn==turn,"batch tickAhead cannot skip hold");}r.tickAhead();ok(b.over&&r.phase==2&&r.settlementQueued&&r.chunkTerminal,"settlement and terminal chunk only at end");
  var ant=HF38SulanRecoveryCheck.room(s,1,0);ant.phase=0;ant.dungeonStage=1;ant.start();ant.phase=1;ant.battle.botPhase=0;int waves=0;while(ant.antKills<20&&waves++<10){for(int slot:AntCaveRules.ANTS)ant.battle.units[slot].hp=0;ant.battle.check();Dungeon780.progress(ant);if(ant.antKills<20){ok(!ant.battle.ending()&&!ant.battle.over,"intermediate wave is not a result");ant.battle.pendingNext=false;}}ok(ant.antKills==20&&ant.battle.ending(),"final ant wave uses result hold");delay(ant.battle,0);
  var last=HF38SulanRecoveryCheck.room(s,1,0);last.phase=0;last.dungeonStage=1;last.start();last.phase=1;Battle f=last.battle;f.botPhase=0;f.active=0;f.units[0].human=true;f.units[0].hp=f.units[0].maxHp=30000;f.units[0].weapon=3;f.units[0].angle=40;f.units[0].power=70;int victim=AntCaveRules.firstAnt(f,1);for(int slot:AntCaveRules.ANTS)if(slot!=victim){f.units[slot].hp=0;f.units[slot].dead=true;}f.units[victim].hp=1;last.antAlive=1<<victim;last.antSpawned=20;last.antKills=19;f.extra=2;f.fire();for(int i=0;i<1500&&!f.ending();i++){if(f.ballCount>0)aimAt(f,victim);last.tick();if(f.shotSerial<3)ok(!f.over&&!f.ending()&&!last.settlementQueued,"last ant does not cancel remaining shots");}ok(f.shotSerial==3&&last.antKills==20&&f.ending()&&!last.chunkTerminal,"last ant uses complete action and delay before terminal chunk");for(int i=0;i<Battle.RESULT_DELAY_TICKS;i++)last.tickAhead();ok(f.over&&f.winner==0&&last.chunkTerminal,"ant room final result follows hold");
 }}
 public static void main(String[] args)throws Exception{for(int stage:new int[]{0,2,3,4,6})for(int d=0;d<3;d++){volley(stage,d,3,false);volley(stage,d,3,true);}golden();redWipe();damage();room();System.out.println("PASS "+checks+" HF42 full-turn, result hold, critical/penetration visual checks");}
}
